function escapeHTML(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function showToast(msg){const x=document.createElement('div');x.className='toast';x.textContent=msg;document.body.appendChild(x);setTimeout(()=>x.remove(),2200)}
function modal(title,body,onSubmit){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>${escapeHTML(title)}</h2><button class="close" id="closeModal">×</button></div>${body}</div></div>`;document.getElementById('closeModal').onclick=()=>root.innerHTML='';const form=root.querySelector('form');if(form)form.onsubmit=e=>{e.preventDefault();onSubmit(new FormData(form));}}
function navBase(role){return role==='ADMIN'?[['inicio','Inicio','⌂'],['usuarios','Usuarios','♙'],['materias','Materias','▦'],['avisos','Avisos','!'],['reportes','Reportes','⚑']]:role==='SOPORTE'?[['inicio','Inicio','⌂'],['reportes','Reportes','⚑']]:[['inicio','Inicio','⌂'],['tareas','Tareas','✓'],['calendario','Calendario','□'],['materias','Materias','▦'],['plataformas','Plataformas','↗'],...(role==='ALUMNO'?[['reportes','Reportes','⚑']]:[]),['avisos','Avisos','!']]}
function setupShell(role){const u=currentUser();if(!u)return;document.getElementById('roleLabel').textContent=u.rol;document.getElementById('userName').textContent=u.nombre;document.getElementById('userEmail').textContent=u.email;document.getElementById('avatar').textContent=u.nombre.split(' ').map(x=>x[0]).slice(0,2).join('');const nav=document.getElementById('nav');nav.innerHTML=navBase(role).map(([id,t,icon])=>`<button class="nav-btn" data-section="${id}"><span>${icon}</span><span>${t}</span></button>`).join('');document.getElementById('logoutBtn').onclick=logout;document.getElementById('themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('ce_dark',document.body.classList.contains('dark'))};if(localStorage.getItem('ce_dark')==='true')document.body.classList.add('dark');document.getElementById('menuBtn').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');return u}
if(location.pathname.endsWith('/')||location.pathname.endsWith('index.html')){
 const form=document.getElementById('loginForm');
 if(form){document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{document.getElementById('email').value=b.dataset.demo;document.getElementById('password').value='123456'});form.onsubmit=e=>{e.preventDefault();const ok=login(email.value,password.value);if(!ok){loginError.textContent='Correo, contraseña o usuario inactivo incorrecto.';return}const u=currentUser();const map={ADMIN:'admin',ALUMNO:'alumno',PADRE:'padre',SOPORTE:'soporte'};location.href='pages/'+map[u.rol]+'.html'}}}
